const s = $('Store Settings').first().json;
const kws = [].concat(s.keywords || []);
const all = (($input.first().json.output || {}).angles || []).filter(a => a && a.search_phrase);
// The angle cap is per keyword: each keyword keeps up to max_angles of its own angles.
const byKw = new Map();
for (const a of all) {
  const k = kws.find(x => x.toLowerCase() === String(a.keyword || '').toLowerCase()) || a.keyword || kws[0];
  if (!byKw.has(k)) byKw.set(k, []);
  if (byKw.get(k).length < s.max_angles) byKw.get(k).push(a);
}
if (!byKw.size) throw new Error('The planner returned no angles');
// One item per keyword: Google Trends is asked once per keyword, with its wide angle's short term (the first angle).
return [...byKw.entries()].map(([keyword, angles]) => ({ json: { run_id: s.run_id, keywords: kws, keyword, angle: keyword,
  search_phrase: angles[0].search_phrase, trends_term: angles[0].trends_term || '',
  angles: angles.map(a => ({ angle: a.angle, search_phrase: a.search_phrase, word_groups: a.word_groups || [] })),
  source: 'google_trends', mode: s.mode, window_days: s.window_days, trend_terms: [], check_duplicates: s.check_duplicates } }));

const errText = (e) => String(typeof e === 'string' ? e : (e && (e.message || e.description || JSON.stringify(e))) || 'unknown error').replace(/\s+/g, ' ').slice(0, 160);
const at = (it, idx) => (it.pairedItem && typeof it.pairedItem.item === 'number') ? it.pairedItem.item : idx;
const label = { google_trends: 'Google Trends', reddit: 'Reddit', hacker_news: 'Hacker News', x: 'X' };
const angles = $('Split Angles').all().map(i => i.json);
const calls = $('Build Source Calls').all().map(i => i.json);
const empty = [], failed = [], problems = [];
$('Collect Google Trends (via Collect Findings)').all().forEach((it, idx) => {
  if (!(it.json.status === 'failed' || (it.json.error && !('status' in it.json)))) return;
  const a = angles[at(it, idx)] || {};
  failed.push(`Google Trends for "${a.keyword}"`); problems.push(`Google Trends failed for "${a.keyword}": ${errText(it.json.error)}`);
});
$input.all().forEach((it, idx) => {
  const c = calls[at(it, idx)] || {};
  const name = `${label[c.source] || c.source} for "${c.angle}"`;
  if (it.json.status === 'failed' || (it.json.error && !('status' in it.json))) { failed.push(name); problems.push(`${name} failed: ${errText(it.json.error)}`); }
  else if (it.json.status === 'empty') empty.push(name);
  if (it.json.status !== 'failed' && it.json.failed_searches) problems.push(`${name}: ${it.json.failed_searches} of ${it.json.searches} searches failed (${errText(it.json.error)}); the others were used.`);
});
// A real result always has a status (ok / empty) or an error. Items without both are the call's own inputs: n8n lost the results
// (seen 2026-11-17: after a sub-workflow failed, Collect From Sources failed inside n8n and passed its inputs on). Say so, never stay silent.
const lost = (node) => $(node).all().filter(it => !it.json.error && !('status' in it.json)).length;
const lostTrends = lost('Collect Google Trends (via Collect Findings)');
const lostCalls = lost('Collect From Sources (via Collect Findings)');
if (lostTrends) { failed.push(`Google Trends results lost for ${lostTrends} keyword(s) (n8n error)`);
  problems.push(`Google Trends results lost (n8n internal error in Collect Google Trends): ${lostTrends} keyword(s) came back without their result, so their rising terms were not used and a failed search could not be named. See this run's "Collect Findings" executions.`); }
if (lostCalls) { failed.push(`results of ${lostCalls} of ${calls.length} source calls lost (n8n error)`);
  problems.push(`Collection results lost (n8n internal error in Collect From Sources): ${lostCalls} of ${calls.length} source calls came back without their result, so failed or empty sources in this run could not be named. The posts that were saved are still used. See this run's "Collect Findings" executions.`); }
const byAngle = {};
for (const c of calls) byAngle[c.angle] = { angle: c.angle, search_phrase: c.search_phrase, trend_terms: c.trend_terms || [] };
const list = Object.values(byAngle);
return [{ json: { angles: list, empty_sources: empty, failed_sources: failed, problems,
  search_terms: [...new Set(list.flatMap(a => [a.search_phrase, ...a.trend_terms]).filter(Boolean))],
  trend_terms: [...new Set(list.flatMap(a => a.trend_terms))] } }];

const recs = $('Read Kept Findings (Airtable Findings)').all().flatMap(i => i.json.records || []) || [];
const findings = recs.map((r, i) => ({ id: 'f' + (i + 1), record_id: r.id, ...r.fields }));
// Stories reported in the last 7 days are only used on scheduled runs (check_duplicates).
const s = $('Store Settings').first().json;
const recent = s.check_duplicates ? ($('Read Recent Claims (Airtable Clusters)').first().json.records || []).map(r => r.fields.title).filter(Boolean) : [];
const lines = findings.map(f => JSON.stringify({ id: f.id, title: f.title, summary: f.summary, source: f.source, angle: f.angle, links_to: f.linked_url || null })).join('\n');
return [{ json: { findings, lines, recent: recent.slice(0, 40), trend_terms: $('Summarise Collection').first().json.trend_terms } }];

const host = (u) => { const m = String(u || '').match(/^https?:\/\/([^\/?#:]+)/i); return m ? m[1].replace(/^www\./, '').toLowerCase() : ''; };
const s = $('Store Settings').first().json;
const gi = $('Build Grouping Input').first().json;
const byId = Object.fromEntries(gi.findings.map(f => [f.id, f]));
const used = new Set();
const groups = [];
for (const g of ($json.output.groups || [])) {
  const ids = (g.finding_ids || []).filter(id => byId[id] && !used.has(id));
  ids.forEach(id => used.add(id));
  if (ids.length) groups.push({ title: g.title, ids, repeat: g.repeat_of_recent === true, trend_terms: g.trend_terms || [] });
}
for (const f of gi.findings) if (!used.has(f.id)) groups.push({ title: f.title, ids: [f.id], repeat: false, trend_terms: [] });
const isPlatform = (h) => /(^|\.)(reddit\.com|redd\.it|news\.ycombinator\.com|x\.com|twitter\.com)$/i.test(h);
const weigh = (g) => {
  const doms = new Set();
  for (const id of g.ids) { const h = host(byId[id].linked_url); if (h && !isPlatform(h)) doms.add(h); else doms.add('platform:' + byId[id].source); }
  return doms.size;
};
const fresh = groups.filter(g => !g.repeat).map(g => ({ ...g, weight: weigh(g) }));
const repeats = groups.length - fresh.length;
fresh.sort((a, b) => b.weight - a.weight || b.ids.length - a.ids.length);
// The check cap is per keyword: each keyword's claims with the most sources are checked, so one keyword never takes the checks of another.
const kwOf = {};
$('Split Angles').all().forEach(i => (i.json.angles || []).forEach(a => { kwOf[a.angle] = i.json.keyword; }));
const kwOfGroup = (g) => { const n = {}; for (const id of g.ids) { const k = kwOf[byId[id].angle] || ''; n[k] = (n[k] || 0) + 1; } return Object.entries(n).sort((a, b) => b[1] - a[1])[0][0]; };
const perKw = {};
const keep = fresh.filter(g => { const k = kwOfGroup(g); perKw[k] = (perKw[k] || 0) + 1; return perKw[k] <= s.max_verify; }).map((g, i) => ({ ...g, cluster_id: 'c' + (i + 1) }));
const plan = { clusters: keep.map(g => ({ cluster_id: g.cluster_id, title: g.title, trend_terms: g.trend_terms,
  finding_record_ids: g.ids.map(id => byId[id].record_id), sources: [...new Set(g.ids.map(id => byId[id].source))] })),
  repeats, not_checked_small: Math.max(0, fresh.length - keep.length) };
const recs = keep.map(g => ({ fields: { title: g.title.slice(0, 200), run_id: s.run_id, cluster_id: g.cluster_id,
  sources: [...new Set(g.ids.map(id => byId[id].source))], independent_domains: 0 } }));
const out = [];
for (let i = 0; i < recs.length; i += 10) out.push({ json: { records: recs.slice(i, i + 10), plan } });
if (!out.length) out.push({ json: { records: [], plan } });
return out;

const plan = $('Build Cluster Rows').first().json.plan;
const ups = plan.clusters.flatMap(c => c.finding_record_ids.map(id => ({ id, fields: { cluster_id: c.cluster_id } })));
const out = [];
for (let i = 0; i < ups.length; i += 10) out.push({ json: { records: ups.slice(i, i + 10) } });
return out;

const s = $('Store Settings').first().json;
const plan = $('Build Cluster Rows').first().json.plan;
// A claim whose check failed comes back from Verify Claim as an error item: it is shown as "Not checked".
const checks = $('Split Claims').all().map(i => i.json);
const notChecked = new Set($('Check Each Claim (via Verify Story)').all().map((it, idx) => it.json.error ? (checks[(it.pairedItem && typeof it.pairedItem.item === 'number') ? it.pairedItem.item : idx] || {}).cluster_id : null).filter(Boolean));
const findings = Object.fromEntries(($('Read Kept Findings (Airtable Findings)').all().flatMap(i => i.json.records || []) || []).map(r => [r.id, r.fields]));
const order = { 'Corroborated': 0, 'Disputed': 1, 'Single source': 2, 'Unverified': 3, 'Opinion': 4, 'Not checked': 5 };
const sources = []; const nOf = {};
const cite = (url, title, date, when) => { if (!nOf[url]) { sources.push({ n: sources.length + 1, url, title, date: date || '', when: when || '' }); nOf[url] = sources.length; } return nOf[url]; };
// Who wrote a post, from its address: @name on X, r/name on Reddit, or Hacker News.
const whoOf = (u) => { let m = String(u).match(/(?:x|twitter)\.com\/([^\/?#]+)\/status/i); if (m) return '@' + m[1] + ' on X'; m = String(u).match(/reddit\.com\/r\/([^\/?#]+)/i); if (m) return 'r/' + m[1] + ' on Reddit'; return /ycombinator/.test(String(u)) ? 'Hacker News' : ''; };
const linkOf = (e) => ({ url: e.url, date: e.published || '', when: e.when || '' });
const claims = ($json.records || []).map(r => {
  const f = r.fields; const p = plan.clusters.find(c => c.cluster_id === f.cluster_id) || {};
  const label = notChecked.has(f.cluster_id) ? 'Not checked' : (f.label || 'Not checked');
  let ev = []; try { ev = JSON.parse(f.evidence || '[]'); } catch (e) { ev = []; }
  const used = ev.filter(e => e.read_status === 'read' && (e.stance === 'supports' || e.stance === 'contradicts')).slice(0, 5)
    .map(e => ({ n: cite(e.url, e.domain, e.published, e.when), stance: e.stance, tier: e.tier, domain: e.domain, date: e.published || '', when: e.when || '', excerpt: e.excerpt }));
  const posts = (p.finding_record_ids || []).map(id => findings[id]).filter(Boolean)
    .sort((a, b) => String(a.published_at || '').localeCompare(String(b.published_at || '')))
    .map(fd => ({ n: cite(fd.url, (({ reddit: 'Reddit: ', hacker_news: 'Hacker News: ', x: 'X: ' })[fd.source] || '') + fd.title, String(fd.published_at || '').slice(0, 10), 'post'), source: fd.source, date: String(fd.published_at || '').slice(0, 10), summary: fd.summary }));
  return { record_id: r.id, cluster_id: f.cluster_id, title: f.title, label, reason: f.reason || '', independent_domains: f.independent_domains || 0,
    evidence: used, posts, trend_terms: p.trend_terms || [],
    origin_links: posts.map(x => ({ url: sources[x.n - 1].url, date: x.date, when: 'post', who: whoOf(sources[x.n - 1].url) })),
    backing_links: ev.filter(e => e.stance === 'supports').map(linkOf),
    contradicting_links: ev.filter(e => e.stance === 'contradicts').map(linkOf),
    page_dates: Object.fromEntries(ev.map(e => [e.url, { date: e.published || '', when: e.when || '' }])),
    single_source: label === 'Single source' ? ((ev.find(e => e.stance === 'supports' && (e.tier === 'official' || e.tier === 'reliable')) || {}).domain || '') : '' };
}).sort((a, b) => order[a.label] - order[b.label]);
const xml = claims.map(c => [
  `<claim id="${c.cluster_id}" label="${c.label}">`,
  `<statement>${c.title}</statement>`,
  ...c.evidence.map(e => `<evidence n="${e.n}" stance="${e.stance}" tier="${e.tier}" domain="${e.domain}" date="${e.date || 'unknown'}" when="${e.when || 'unknown'}">${e.excerpt}</evidence>`),
  ...c.posts.map(x => `<post n="${x.n}" source="${x.source}" date="${x.date || 'unknown'}">${x.summary}</post>`),
  c.trend_terms.length ? `<search_interest>${c.trend_terms.join('; ')}</search_interest>` : '',
  '</claim>'].filter(Boolean).join('\n')).join('\n');
return [{ json: { claims, sources, claims_xml: xml, topic: [].concat(s.keywords || []).join(', '),
  window: s.mode === 'today' ? 'last 24 hours' : 'last 7 days' } }];

const s = $('Store Settings').first().json;
const wi = $('Build Writer Input').first().json;
const col = $('Summarise Collection').first().json;
const plan = $('Build Cluster Rows').first().json.plan;
const out = $json.output || {};
// What Verify Story returned for each claim (explainer, links, search words), by cluster id.
const verified = Object.fromEntries($('Check Each Claim (via Verify Story)').all().map(i => i.json).filter(j => j && j.cluster_id && !j.error).map(j => [j.cluster_id, j]));
const byId = Object.fromEntries(wi.claims.map(c => [c.cluster_id, c]));
const maxN = wi.sources.length;
const doubt = ['Disputed', 'Unverified', 'Not checked', 'Opinion', 'Single source', 'Corroborated'];
const cleanCites = (t) => String(t || '').replace(/\[(\d+)\]/g, (m, n) => (Number(n) >= 1 && Number(n) <= maxN) ? m : '');
const flagOf = (ids) => { const labels = ids.map(id => byId[id].label); return doubt.find(l => labels.includes(l)); };
const sections = (out.sections || []).map(sec => {
  const paragraphs = (sec.paragraphs || []).map(p => {
    const ids = (p.cluster_ids || []).filter(id => byId[id]);
    if (!ids.length) return null;
    const flag = flagOf(ids);
    const src = flag === 'Single source' ? (ids.map(id => byId[id].single_source).find(Boolean) || '') : '';
    return { text: cleanCites(p.text), flag, flag_source: src, cluster_ids: ids };
  }).filter(Boolean);
  const os = sec.other_side || {};
  return { topic: sec.topic, paragraphs, search_interest: sec.search_interest || [],
    other_side: { text: cleanCites(os.text) || 'No contradicting source found.' } };
}).filter(sec => sec.paragraphs.length);
const gists = Object.fromEntries((out.gists || []).filter(g => byId[g.cluster_id]).map(g => [g.cluster_id, g.gist]));
const d = new Date();
const report = { run_id: s.run_id, title: wi.topic, date_text: d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }),
  window_text: s.mode === 'today' ? 'last 24 hours (Hacker News: last 7 days)' : 'last 7 days', keywords: [].concat(s.keywords || []),
  search_terms: col.search_terms, briefing: { in_short: cleanCites(out.in_short), sections },
  claims: wi.claims.map(c => ({ cluster_id: c.cluster_id, title: c.title, label: c.label, independent_domains: c.independent_domains, gist: gists[c.cluster_id] || '',
    explainer: (verified[c.cluster_id] || {}).explainer || null,
    origin_links: c.origin_links, backing_links: c.backing_links, contradicting_links: c.contradicting_links, page_dates: c.page_dates })),
  sources: wi.sources,
  footer: { empty_sources: col.empty_sources, failed_sources: col.failed_sources,
    not_checked: wi.claims.filter(c => c.label === 'Not checked').map(c => c.title), already_reported: plan.repeats, smaller_claims: plan.not_checked_small } };
const md = ['## In short', report.briefing.in_short, ''];
for (const sec of sections) {
  md.push('## ' + sec.topic);
  for (const p of sec.paragraphs) md.push('[' + p.flag + (p.flag_source ? ': ' + p.flag_source : '') + '] ' + p.text, '');
  if (sec.search_interest.length) md.push('Search interest: ' + sec.search_interest.join(', '), '');
  md.push('### The other side', sec.other_side.text, '');
}
md.push('## Sources', ...wi.sources.map(x => x.n + '. ' + x.url));
// One archive row per checked story (Not checked claims are not archived); Save Or Update Stories In Archive gives each its number.
const today = $now.setZone('Europe/Rome').toISODate();
// The claim's original posts, oldest first: dig shows them, and a later run that finds one of them (or the article it links to) again has found the same story.
const kept = Object.fromEntries(($('Read Kept Findings (Airtable Findings)').all().flatMap(i => i.json.records || []) || []).map(r => [r.id, r.fields]));
const postsOf = (cid) => { const p = plan.clusters.find(x => x.cluster_id === cid) || {};
  return (p.finding_record_ids || []).map(id => kept[id]).filter(f => f && f.url)
    .map(f => ({ source: f.source || '', url: f.url, linked_url: f.linked_url || '', published_at: f.published_at || '', title: f.title || '' }))
    .sort((a, b) => a.published_at.localeCompare(b.published_at)); };
const archive_rows = wi.claims.filter(c => c.label !== 'Not checked' && verified[c.cluster_id]).map(c => { const v = verified[c.cluster_id];
  return { run_id: s.run_id, cluster_id: c.cluster_id, found_on: today, mode: s.mode, keywords: [].concat(s.keywords || []).join(', '),
    title: c.title, label: c.label, claim: v.claim || c.title, gist: gists[c.cluster_id] || '', explainer: v.explainer || null,
    official_links: v.official_links || '', supporting_links: v.supporting_links || '', contradicting_links: v.contradicting_links || '',
    evidence: v.evidence || '[]', search_terms: v.search_terms || '', posts: postsOf(c.cluster_id) }; });
return [{ json: { report, markdown: md.join('\n'), archive_rows,
  cluster_updates: wi.claims.map(c => ({ id: c.record_id, cluster_id: c.cluster_id, fields: gists[c.cluster_id] ? { gist: gists[c.cluster_id] } : {} })) } }];

const s = $('Store Settings').first().json;
const col = $('Summarise Collection').first().json;
const plan = $('Build Cluster Rows').isExecuted ? $('Build Cluster Rows').first().json.plan : { repeats: 0, not_checked_small: 0 };
const d = new Date();
const msg = plan.repeats ? 'Every story found in this run was already reported in the last 7 days.' : 'No usable posts were found for these keywords in this window.';
return [{ json: { markdown: '## In short\n' + msg, report: { run_id: s.run_id, title: [].concat(s.keywords || []).join(', '),
  date_text: d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }),
  window_text: s.mode === 'today' ? 'last 24 hours (Hacker News: last 7 days)' : 'last 7 days', keywords: [].concat(s.keywords || []),
  search_terms: col.search_terms, briefing: { in_short: msg, sections: [] }, claims: [], sources: [],
  footer: { empty_sources: col.empty_sources, failed_sources: col.failed_sources, not_checked: [], already_reported: plan.repeats, smaller_claims: 0 } } } }];

// Build Report HTML: turns the checked briefing + claims into one HTML page that Google Drive converts to a Doc.
const r = ($('Check Briefing Flags').isExecuted ? $('Check Briefing Flags') : $('Build Empty Report')).first().json.report;
const s = $('Store Settings').first().json;
// Permanent story numbers from the archive (none for an empty run).
const nums = Object.fromEntries((($('Save Or Update Stories In Archive').isExecuted ? $('Save Or Update Stories In Archive').first().json.saved : null) || []).map(x => [x.cluster_id, x.story_number]));

// The answer to a question keyword (from "Answer Question"), shown before In short.
const ans = $('Answer The Question (via Answer Question)').isExecuted ? ($('Answer The Question (via Answer Question)').first().json.answer || null) : null;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const FLAG = {
  'Corroborated':  { bg: '#E3F1E1', fg: '#1E5A1A', text: 'Corroborated' },
  'Single source': { bg: '#E3ECF8', fg: '#1C3F73', text: 'Single source' },
  'Disputed':      { bg: '#FBE3DF', fg: '#8A2416', text: 'Disputed' },
  'Unverified':    { bg: '#F6EDD6', fg: '#6B4E0B', text: 'Unverified' },
  'Opinion':       { bg: '#ECE9F5', fg: '#43376E', text: 'Opinion' },
  'Not checked':   { bg: '#EEEEEE', fg: '#444444', text: 'Not checked' },
};
const srcByN = Object.fromEntries((r.sources || []).map(s => [String(s.n), s]));
const badge = (label, extra) => {
  const f = FLAG[label] || FLAG['Not checked'];
  return `<span style="background-color:${f.bg};color:${f.fg};font-weight:bold;font-size:9pt;">&nbsp;${esc(f.text)}${extra ? ': ' + esc(extra) : ''}&nbsp;</span>`;
};
// Escape the text, then turn [n] into a link to source n.
const cite = (text) => esc(text).replace(/\[(\d+)\]/g, (m, n) => srcByN[n] ? `<a href="${esc(srcByN[n].url)}">[${n}]</a>` : m);
const linkList = (arr) => (arr && arr.length)
  ? arr.slice(0, 4).map(u => `<a href="${esc(u)}">${esc((String(u).match(/^https?:\/\/(?:www\.)?([^\/?#:]+)/i) || [, u])[1])}</a>`).join('<br>') + (arr.length > 4 ? `<br>+${arr.length - 4} more` : '')
  : '<span style="color:#888888;">none</span>';

const h = [];
h.push('<html><head><meta charset="utf-8"></head><body style="font-family:Arial;font-size:11pt;color:#222222;">');

// Front page
h.push(`<h1 style="font-size:22pt;">Claim Checks: ${esc(r.title)}</h1>`);
h.push(`<p style="color:#555555;">${esc(r.date_text)} &middot; window: ${esc(r.window_text)} &middot; run ${esc(r.run_id)}</p>`);
h.push(`<p><b>Keywords:</b> ${esc((r.keywords || []).join(', '))}<br><b>Search terms used:</b> ${esc((r.search_terms || []).join(', '))}</p>`);
h.push('<h3>How to read the labels</h3><table style="border-collapse:collapse;width:100%;" border="1" cellpadding="6">');
const legend = [
  ['Corroborated', 'At least two independent sources back it, one of them official or a reliable outlet, and nothing trustworthy contradicts it. Backed, not proven.'],
  ['Single source', 'One official source or reliable outlet has stated it so far. Typical for fresh news.'],
  ['Disputed', 'An official source or reliable outlet says otherwise. Both sides are shown.'],
  ['Unverified', 'Being discussed, but no trustworthy source confirms it.'],
  ['Opinion', 'A view, not a checkable fact.'],
];
for (const [l, d] of legend) h.push(`<tr><td style="width:24%;">${badge(l)}</td><td>${esc(d)}</td></tr>`);
h.push('</table>');

// Answer (question runs only): code-built from the answer object, each item with its status and dated links.
if (ans) {
  const ASTATUS = { confirmed: ['Corroborated', 'Confirmed'], claimed: ['Single source', 'Claimed by its team'], unverified: ['Unverified', 'Unverified'] };
  const abadge = (st) => { const [l, t] = ASTATUS[st] || ASTATUS.unverified; const f = FLAG[l]; return `<span style="background-color:${f.bg};color:${f.fg};font-weight:bold;font-size:9pt;">&nbsp;${esc(t)}&nbsp;</span>`; };
  const aday = (d) => d ? new Date(String(d).slice(0, 10) + 'T12:00:00Z').toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' }) : 'date unknown';
  h.push('<h2 style="font-size:16pt;">Answer</h2>');
  h.push(`<p><i>${esc(ans.question)}</i></p>`);
  h.push(`<p>${esc(ans.summary || 'No answer was found on the web.')}</p>`);
  if ((ans.items || []).length) {
    h.push('<table style="border-collapse:collapse;width:100%;" border="1" cellpadding="6"><tr><th style="width:56%;">Answer</th><th style="width:18%;">Status</th><th>Sources</th></tr>');
