const queryFor = (a, source) => {
  const groups = [].concat(a.word_groups || []).map(g => [].concat(g || []).map(w => String(w).replace(/["()#]/g, '').trim()).filter(Boolean).slice(0, 12)).filter(g => g.length).slice(0, 3);
  if (!groups.length) return a.search_phrase;
  if (source === 'hacker_news') return [...new Set(groups.flat())].join(' ');
  return groups.map(g => '(' + g.map(w => /\s/.test(w) ? '"' + w + '"' : w).join(' OR ') + ')').join(' ');
};
